<script setup lang="ts">
import { computed,onMounted,onBeforeUnmount,ref,watch } from 'vue'
import { payslipPostedLabel } from '~~/shared/utils/payslipPresentation'
import { archiveCutoffs } from '~~/shared/utils/payslipArchiveImport'
type Selection={key:string;start:string;end:string;label:string;file:File;url:string;agencyName:string;siteLabel:string;error:string}
const emit=defineEmits<{processing:[value:boolean];dirty:[value:boolean]}>()
const props=defineProps<{employeeId?:number;agencyName?:string|null;employee?:{EmployeeID:number;EmployeeNumber?:string|null;EmployeeName:string;AgencyName?:string|null}}>()
const staff=computed(()=>Boolean(props.employeeId)),items=ref<any[]>([]),canManage=ref(false),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),search=ref(''),status=ref('')
const currentYear=Number(new Intl.DateTimeFormat('en',{timeZone:'Asia/Singapore',year:'numeric'}).format(new Date()))
const year=ref(staff.value?String(currentYear):''),month=ref(''),selections=ref<Record<string,Selection>>({}),review=ref<any>(null),ownership=ref(false),fileInput=ref<HTMLInputElement|null>(null),progress=ref('')
let owner=0,loadOwner=0,controller:AbortController|null=null,operationController:AbortController|null=null,uploadTarget:any=null
const selectedFiles=computed(()=>Object.values(selections.value).sort((a,b)=>a.start.localeCompare(b.start)))
watch(busy,value=>emit('processing',value));watch(()=>selectedFiles.value.length,value=>emit('dirty',value>0))
const years=computed(()=>staff.value?[...new Set([...Array.from({length:currentYear-1900+1},(_,index)=>String(currentYear-index)),...items.value.map(item=>item.PeriodStart.slice(0,4))])].sort().reverse():[...new Set(items.value.map(item=>item.PeriodEnd.slice(0,4)))].sort().reverse())
const months=Array.from({length:12},(_,index)=>({value:String(index+1).padStart(2,'0'),label:new Date(Date.UTC(2026,index,1)).toLocaleDateString('en-PH',{month:'long',timeZone:'Asia/Singapore'})}))
const day=(value:string)=>new Date(value+'T00:00:00Z').toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric',timeZone:'Asia/Singapore'})
const period=(item:any)=>day(item.PeriodStart)+' - '+day(item.PeriodEnd)
const fileUrl=(item:any,download=false)=>(staff.value?'/api/payroll/payslips/archive/':'/api/employee-portal/archive/')+item.ArchiveID+(download?'?download=1':'')
const visible=computed(()=>items.value.filter(item=>(!year.value||item.PeriodEnd.startsWith(year.value))&&[item.PeriodStart,item.PeriodEnd,item.AgencyName,item.SiteLabel,item.FileName].join(' ').toLowerCase().includes(search.value.toLowerCase().trim())))
const cutoffs=computed(()=>{
 const map=new Map(archiveCutoffs(Number(year.value)).map(cutoff=>[cutoff.key,{...cutoff,records:[] as any[]}]))
 for(const item of items.value){if(item.Status==='Removed'||!item.PeriodStart.startsWith(year.value))continue;const key=item.PeriodStart+':'+item.PeriodEnd;if(!map.has(key))map.set(key,{key,start:item.PeriodStart,end:item.PeriodEnd,label:period(item),records:[]});map.get(key)!.records.push(item)}
 return [...map.values()].sort((a,b)=>b.start.localeCompare(a.start)).filter(cutoff=>{
  if(month.value&&cutoff.start.slice(5,7)!==month.value)return false
  if(status.value==='missing'&&cutoff.records.some(item=>item.Status!=='Removed'))return false
  if(status.value==='selected'&&!selections.value[cutoff.key])return false
  if(['Draft','Posted','Withdrawn'].includes(status.value)&&!cutoff.records.some(item=>item.Status===status.value))return false
  return [cutoff.label,cutoff.start,cutoff.end,...cutoff.records.map(item=>item.FileName),selections.value[cutoff.key]?.file.name].join(' ').toLowerCase().includes(search.value.toLowerCase().trim())
 })
})
async function load(){const current=++loadOwner;controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const result:any=await $fetch(staff.value?'/api/payroll/payslips/archive':'/api/employee-portal/archive',{query:staff.value?{employeeId:props.employeeId}:undefined,signal:controller.signal,retry:0,timeout:15000});if(current===loadOwner){items.value=result.items.filter((item:any)=>item.Status!=='Removed');canManage.value=result.canManage}}catch(cause:any){if(current===loadOwner)error.value=cause?.data?.statusMessage||'Unable to load historical payslips.'}finally{if(current===loadOwner)loading.value=false}}
function chooseUpload(cutoff:any){if(busy.value||review.value||!canManage.value)return;uploadTarget={key:cutoff.key,start:cutoff.start,end:cutoff.end,label:cutoff.label};fileInput.value?.click()}
function chooseFile(event:Event){
 const input=event.target as HTMLInputElement,file=input.files?.[0],target=uploadTarget;input.value='';uploadTarget=null;if(!file||!target||busy.value)return
 if(!/\.pdf$/i.test(file.name)||!file.size||file.size>5*1024*1024){error.value='Choose a PDF of 5 MB or less.';return}
 removeSelection(target.key);selections.value[target.key]={...target,file,url:URL.createObjectURL(file),agencyName:props.agencyName||props.employee?.AgencyName||'',siteLabel:'',error:''};error.value='';notice.value=''
}
function removeSelection(key:string){if(busy.value)return;const item=selections.value[key];if(item)URL.revokeObjectURL(item.url);delete selections.value[key];ownership.value=false}
function reviewUploads(){if(busy.value||!selectedFiles.value.length)return;ownership.value=false;review.value={action:'import',files:selectedFiles.value.map(item=>({...item}))}}
function prepareAction(item:any,action:string){if(busy.value||review.value)return;review.value={action,item}}
async function readFile(file:File){return new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(Error('Unable to read this PDF.'));reader.readAsDataURL(file)})}
async function confirmAction(){
 if(busy.value||!review.value)return;const plan=review.value;if(plan.action==='import'&&!ownership.value)return
 const current=owner;busy.value=true;error.value='';notice.value='';operationController=new AbortController()
 try{
  if(plan.action==='import'){
   let saved=0,failed=0
   for(const [index,item] of plan.files.entries()){
    if(current!==owner)break;progress.value='Saving '+(index+1)+' of '+plan.files.length+' PDFs'
    try{
     const pdfData=await readFile(item.file);if(current!==owner)break
     await $fetch('/api/payroll/payslips/archive',{method:'POST',body:{action:'import',employeeId:props.employeeId,periodStart:item.start,periodEnd:item.end,agencyName:item.agencyName,siteLabel:item.siteLabel,employeeOnly:true,fileName:item.file.name,pdfData},retry:0,timeout:30000,signal:operationController.signal})
     if(current!==owner)break;URL.revokeObjectURL(selections.value[item.key].url);delete selections.value[item.key];saved++
    }catch(cause:any){if(current!==owner)break;if(cause?.data?.data?.code==='ARCHIVE_DUPLICATE'){URL.revokeObjectURL(selections.value[item.key].url);delete selections.value[item.key];saved++}else{failed++;if(selections.value[item.key])selections.value[item.key].error=cause?.data?.statusMessage||cause?.message||'Upload failed. Try again.'}}
   }
   if(current!==owner)return;review.value=null;ownership.value=false;notice.value=saved+' PDF(s) saved or already archived. '+(failed?failed+' upload(s) need attention. Successful uploads are retained.':'Review and post each draft when ready.');await load()
  }else{
   await $fetch('/api/payroll/payslips/archive',{method:'POST',body:{employeeId:props.employeeId,archiveId:plan.item.ArchiveID,expectedStatus:plan.item.Status,action:plan.action},retry:0,timeout:30000,signal:operationController.signal})
   if(current!==owner)return;review.value=null;notice.value='PDF status updated.';await load()
  }
 }catch(cause:any){if(current===owner)error.value=cause?.data?.statusMessage||'Unable to save this action. Please try again.'}finally{busy.value=false;progress.value=''}
}
function clearDrafts(){for(const item of selectedFiles.value)URL.revokeObjectURL(item.url);selections.value={};review.value=null;ownership.value=false}
function warnBeforeUnload(event:BeforeUnloadEvent){if(selectedFiles.value.length||busy.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>{void load();window.addEventListener('beforeunload',warnBeforeUnload)})
watch(()=>props.employeeId,()=>{owner++;operationController?.abort();clearDrafts();void load()})
onBeforeUnmount(()=>{owner++;loadOwner++;controller?.abort();operationController?.abort();clearDrafts();window.removeEventListener('beforeunload',warnBeforeUnload);emit('processing',false);emit('dirty',false)})
</script>
<template>
 <section class="archive-panel" :class="{'employee-view':!staff}">
  <header class="archive-heading"><div><p class="eyebrow">PDF PAYSLIPS</p><h3>Historical payslips</h3><p>{{staff?'Manage this employee\'s payslip PDF for each payroll cutoff.':'View and download the older payslips posted for you by payroll.'}}</p></div><span class="archive-count">{{items.filter(item=>item.Status!=='Removed').length}} archived PDF(s)</span></header>
  <p v-if="error" class="error" role="alert">{{error}} <button type="button" :disabled="busy" @click="load">Reload records</button></p><p v-if="notice" class="success" role="status">{{notice}}</p>
  <input v-if="canManage" ref="fileInput" class="hidden-input" type="file" accept="application/pdf,.pdf" aria-label="Payslip PDF" @change="chooseFile">
  <div class="archive-toolbar"><label>Year<select v-model="year" :disabled="busy||Boolean(review)"><option v-if="!staff" value="">All years</option><option v-for="value in years" :key="value" :value="value">{{value}}</option></select></label><label v-if="staff">Month<select v-model="month"><option value="">All months</option><option v-for="value in months" :key="value.value" :value="value.value">{{value.label}}</option></select></label><label v-if="staff">Status<select v-model="status"><option value="">All cutoffs</option><option value="missing">No PDF uploaded</option><option value="selected">Selected for upload</option><option>Draft</option><option>Posted</option><option>Withdrawn</option></select></label><label class="search">Search<input v-model="search" type="search" placeholder="Cutoff or filename"></label></div>
  <div v-if="staff&&selectedFiles.length&&!review" class="selection-bar"><div><strong>{{selectedFiles.length}} PDF(s) selected</strong><small>Files are assigned to this employee and their selected cutoff.</small></div><button type="button" class="primary" :disabled="busy" @click="reviewUploads">Review uploads</button></div>
  <section v-if="review" class="review" role="region" aria-label="Review PDF action"><h4>{{review.action==='import'?'Review PDF uploads':'Confirm '+review.action}}</h4><p v-if="employee"><strong>{{employee.EmployeeName}}</strong><span v-if="employee.EmployeeNumber"> &middot; {{employee.EmployeeNumber}}</span></p><template v-if="review.action==='import'"><article v-for="item in review.files" :key="item.key" class="review-file"><div><strong>{{item.label}}</strong><small>{{item.file.name}}</small></div><div class="reference-fields"><label>Agency on this payslip<input v-model="item.agencyName" maxlength="200" :disabled="busy"></label><label>Site / assignment (optional)<input v-model="item.siteLabel" maxlength="255" :disabled="busy"></label></div></article><label class="check"><input v-model="ownership" type="checkbox" :disabled="busy">I verified that these PDFs belong to this employee and the listed cutoffs.</label><p>Uploads are saved as drafts. Post a draft when it is ready for the employee.</p></template><p v-else>{{period(review.item)}} &middot; {{review.item.FileName}}. {{review.action==='post'?'This PDF will become visible in this employee\'s Payslip Portal.':'This changes the PDF archive status only.'}}</p><div class="review-actions"><button type="button" :disabled="busy" @click="review=null">Keep editing</button><button type="button" class="primary" :disabled="busy||(review.action==='import'&&!ownership)" @click="confirmAction">{{busy?'Saving...':review.action==='import'?'Confirm upload':'Confirm '+review.action}}</button></div><p v-if="progress" role="status">{{progress}}</p></section>
  <template v-if="staff"><div class="cutoff-table-wrap"><table class="cutoff-table"><thead><tr><th>Payroll cutoff</th><th>PDF payslip</th><th>Actions</th></tr></thead><tbody v-for="cutoff in cutoffs" :key="cutoff.key" class="cutoff-group">
   <tr v-for="(record,index) in [...cutoff.records,...(selections[cutoff.key]?[{selected:true,key:cutoff.key}]:[]),...(!cutoff.records.length&&!selections[cutoff.key]?[null]:[])]" :key="record?.ArchiveID||record?.key||'empty'">
    <td v-if="index===0" class="cutoff-period" :rowspan="Math.max(1,cutoff.records.length+(selections[cutoff.key]?1:0))"><strong>{{cutoff.label}}</strong><button v-if="canManage&&(cutoff.records.length||selections[cutoff.key])" type="button" class="text-button" :disabled="busy||Boolean(review)" :aria-label="'Upload PDF for '+cutoff.label" @click="chooseUpload(cutoff)">{{selections[cutoff.key]?'Change selected PDF':'+ Upload PDF'}}</button></td>
    <td class="document-cell"><template v-if="record?.selected"><span class="badge selected">Selected for upload</span><strong>{{selections[cutoff.key].file.name}}</strong><small v-if="selections[cutoff.key].error" class="file-error" role="alert">{{selections[cutoff.key].error}}</small><small v-else>Ready to review</small></template><template v-else-if="record"><span class="badge" :class="record.Status.toLowerCase()">{{record.Status}}</span><strong>{{record.FileName}}</strong><small>{{record.AgencyName}}<span v-if="record.SiteLabel"> &middot; {{record.SiteLabel}}</span></small></template><span v-else class="no-document">No PDF uploaded</span></td>
    <td class="document-actions"><template v-if="record?.selected"><a :href="selections[cutoff.key].url" target="_blank" rel="noopener">Preview</a><button type="button" :disabled="busy||Boolean(review)" :aria-label="'Remove selected PDF for '+cutoff.label" @click="removeSelection(cutoff.key)">Remove</button></template><template v-else-if="record"><a :href="fileUrl(record)" target="_blank" rel="noopener">View PDF &nearr;</a><template v-if="canManage"><button v-if="['Draft','Withdrawn'].includes(record.Status)" type="button" :disabled="busy||Boolean(review)" @click="prepareAction(record,'post')">Post PDF</button><button v-if="record.Status==='Posted'" type="button" :disabled="busy||Boolean(review)" @click="prepareAction(record,'withdraw')">Withdraw</button><button v-if="['Draft','Withdrawn'].includes(record.Status)" type="button" class="quiet" :disabled="busy||Boolean(review)" @click="prepareAction(record,'remove')">Remove</button></template></template><button v-else-if="canManage" type="button" :disabled="busy||Boolean(review)" :aria-label="'Upload PDF for '+cutoff.label" @click="chooseUpload(cutoff)">Upload PDF</button><span v-else class="no-document">&mdash;</span></td>
   </tr>
  </tbody><tbody v-if="!cutoffs.length"><tr><td colspan="3" class="empty">No cutoffs match these filters.</td></tr></tbody></table></div><p class="archive-footnote">One employee, one cutoff per PDF. Files up to 5 MB and 30 pages are supported.</p></template>
  <div v-else class="archive-list"><article v-for="item in visible" :key="item.ArchiveID"><div><span class="badge posted">Posted</span><h4>{{period(item)}}</h4><p>{{item.AgencyName || 'Historical payslip'}}<span v-if="item.SiteLabel"> &middot; {{item.SiteLabel}}</span></p><small>{{item.FileName}}<span v-if="item.PostedAt"> &middot; Posted {{payslipPostedLabel(item.PostedAt)}}</span></small></div><div class="card-actions"><a :href="fileUrl(item)" target="_blank" rel="noopener">View PDF &nearr;</a><a :href="fileUrl(item,true)" download>Download</a></div></article><p v-if="!visible.length" class="empty">{{loading?'Loading historical payslips...':'No historical PDFs match this view.'}}</p></div>
 </section>
</template>
<style scoped>
.archive-panel{color:#1a3457;font:inherit;min-width:0;margin-top:12px}.archive-panel *{box-sizing:border-box}.archive-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}.eyebrow{margin:0;font-size:.64rem;letter-spacing:.1em;font-weight:800;color:#2b62cc}h3{font-size:1.3rem;margin:7px 0 9px}.archive-heading p:not(.eyebrow){font-size:.81rem;color:#70829c;line-height:1.7;margin:0}.archive-count{font-size:.72rem;color:#6c809e;white-space:nowrap;padding-top:8px}.archive-toolbar{display:grid;grid-template-columns:110px 150px 180px minmax(160px,1fr);gap:12px;margin:0 0 20px;align-items:end}.employee-view .archive-toolbar{grid-template-columns:140px minmax(0,1fr)}.employee-view .archive-toolbar .search{grid-column:auto}label{display:grid;gap:7px;font-size:.74rem;font-weight:700;color:#516a8d;min-width:0}input,select{width:100%;min-width:0;max-width:100%;height:42px;padding:10px 12px;border:1px solid #cedbee;border-radius:8px;background:#fff;color:#1d3b60;font:inherit;font-size:.84rem}input.hidden-input{display:none}button,a{display:inline-flex;align-items:center;justify-content:center;gap:5px;min-height:36px;padding:8px 11px;border:1px solid #cad9ee;border-radius:7px;background:#fff;color:#2b5a9b;font:inherit;font-size:.73rem;font-weight:650;text-decoration:none;white-space:nowrap;cursor:pointer}button:disabled{opacity:.5;cursor:default}.primary{background:#2863dc;border-color:#2863dc;color:#fff}.quiet{border-color:transparent;color:#71849d}.cutoff-table-wrap{border:1px solid #dbe5f2;border-radius:10px;overflow:auto;background:#fff}.cutoff-table{width:100%;border-collapse:collapse;text-align:left}.cutoff-table th{font-size:.63rem;color:#6b809e;background:#f4f7fc;text-transform:uppercase;letter-spacing:.04em;padding:13px 17px}.cutoff-table td{padding:17px;vertical-align:middle;border-top:1px solid #e7edf6;font-size:.79rem}.cutoff-period{width:28%;min-width:200px}.cutoff-period>strong{display:block;font-size:.8rem;line-height:1.6;font-weight:650}.cutoff-period .text-button{padding:0;margin-top:7px;border:0;background:none;min-height:24px;font-size:.69rem;color:#56759e}.document-cell{min-width:200px}.document-cell>strong{display:block;font-size:.77rem;margin:7px 0 4px;overflow-wrap:anywhere;font-weight:550}.document-cell>small{display:block;font-size:.68rem;color:#7b8da6;line-height:1.7;overflow-wrap:anywhere}.document-cell>small.file-error{color:#a23e48}.no-document{color:#8b9aaf;font-size:.75rem}.document-actions{width:29%;min-width:210px}.document-actions>*{margin:3px 5px 3px 0}.badge{display:inline-flex;border-radius:5px;padding:3px 7px;font-size:.63rem;font-weight:700;background:#edf1f7;color:#6c7e98}.badge.posted{background:#e6f5ed;color:#267449}.badge.draft{background:#fff3dc;color:#96681d}.badge.selected{background:#eaf1ff;color:#2a5fa6}.selection-bar{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:16px 18px;background:#f0f5ff;border:1px solid #d4e1f7;border-radius:9px;margin-bottom:20px}.selection-bar strong{display:block;font-size:.84rem}.selection-bar small{display:block;font-size:.71rem;color:#6981a3;margin-top:5px;line-height:1.7}.review{display:grid;gap:15px;padding:22px;background:#f5f8fe;border:1px solid #d2e0f4;border-radius:10px;margin-bottom:22px}.review h4{font-size:1.05rem;margin:0}.review>p{margin:0;font-size:.8rem;line-height:1.8;color:#547091}.review-file{padding:16px;background:#fff;border:1px solid #e0e8f4;border-radius:8px;min-width:0}.review-file strong{font-size:.8rem}.review-file small{display:block;overflow-wrap:anywhere;margin-top:5px;color:#7389a8;font-size:.73rem}.reference-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:15px}.check{display:flex;align-items:flex-start;gap:10px;font-size:.78rem;font-weight:400;line-height:1.8}.check input{width:18px;height:18px;flex:none;margin-top:3px}.review-actions{display:flex;gap:9px}.error,.success{padding:13px 15px;border-radius:8px;font-size:.8rem;line-height:1.8;background:#fff0f1;color:#a13a45;margin:15px 0}.success{background:#ebf7f0;color:#2a7252}.archive-footnote{font-size:.68rem;color:#7a8da7;line-height:1.8;margin:14px 0}.archive-list{display:grid;gap:12px}.archive-list article{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:20px;border:1px solid #dce5f2;border-radius:10px;background:#fff;min-width:0}.archive-list article>div{min-width:0}.archive-list h4{font-size:.95rem;margin:9px 0}.archive-list p{font-size:.8rem;color:#67809e;line-height:1.7}.archive-list small{font-size:.7rem;color:#7a8da7;line-height:1.8;overflow-wrap:anywhere}.card-actions{display:flex;gap:7px;flex-wrap:wrap}.empty{text-align:center;padding:25px;color:#7a8ba6;font-size:.81rem}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #a9c7f5;outline-offset:2px}@media(max-width:1000px){.archive-toolbar{grid-template-columns:1fr 1fr}.archive-toolbar .search{grid-column:1/-1}}@media(max-width:700px){.archive-panel:not(.employee-view) .archive-toolbar>label:nth-child(3){grid-column:1/-1}.archive-heading{flex-direction:column;gap:6px}.archive-toolbar{grid-template-columns:1fr 1fr}.archive-toolbar label{font-size:.72rem}input,select{font-size:16px}.cutoff-table,.cutoff-table tbody,.cutoff-table tr,.cutoff-table td{display:block;width:100%;min-width:0}.cutoff-table thead{display:none}.cutoff-group{border-top:1px solid #dce5f2;padding:15px}.cutoff-group:first-of-type{border-top:0}.cutoff-table td{padding:8px 0;border:0}.cutoff-table td.cutoff-period{padding-top:0}.cutoff-period>strong{font-size:.87rem}.cutoff-table td.document-actions{padding-bottom:6px}.document-actions>*{margin-block:3px}.selection-bar{align-items:flex-start;flex-direction:column}.reference-fields{grid-template-columns:1fr}.review{padding:16px}.archive-list article{flex-direction:column;align-items:flex-start}.card-actions{width:100%}.card-actions a{flex:1}}
</style>
